bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || { echo STK01_LIVE_NOT_RUNNING;exit 61; }
test "$(docker ps --filter label=com.docker.compose.project=gace-createvdobot --filter label=com.docker.compose.service=videobot-poll -q | wc -l)" -eq 1 || exit 62
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';
import pg from 'pg';
import {createPostgresCreatorSessionStore} from './src/sales/pgCreatorSessions.mjs';
const env=process.env;
const pool=new pg.Pool({host:env.VIDEOBOT_DB_HOST,user:env.VIDEOBOT_DB_USER,
 database:env.VIDEOBOT_DB_NAME,
 password:readFileSync(env.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),
 connectionTimeoutMillis:5000,max:1});
try{
 const store=createPostgresCreatorSessionStore(pool);
 const rows=await store.listPendingStickerRegistrations({afterOwnerId:0,limit:10});
 if(!Array.isArray(rows)||rows.some(r=>!Number.isSafeInteger(r.ownerId)||r.ownerId<=0))
  throw Error('RECOVERY_QUERY_SHAPE_INVALID');
 console.log('STK01_LIVE_RECOVERY_DB_QUERY=PASS');
 console.log('STK01_RECOVERY_PENDING_FIRST_PAGE_COUNT='+rows.length);
}catch(e){
 console.log('STK01_LIVE_RECOVERY_DB_QUERY=FAIL');
 process.exitCode=1;
}finally{await pool.end();}
NODE
docker logs --tail 200 "$cid" 2>&1 | grep -Fq 'CREATOR_DM_POLL_READY=PASS' || exit 63
echo STK01_RECOVERY_LIVE_POLLER=PASS
